out=out.replace(/(\b\d+(?:[.,]\d+)?\s?%)(?=\s|[.,;:!?)]|$)/g,"<strong>$1</strong>");
out=out.replace(/(\b\d[\d\s.,]*(?:\s?[–-]\s?\d[\d\s.,]*)?\s?(?:МВт·год|МВт|ГВт·год|ГВт|MW|MWh|GW|GWh|кВт|kW|%|млн т|million tonnes|рок(?:ів|и|у)?|years?|турбін(?:и|а)?|двигун(?:ів|и)?|установок|контейнер(?:ів|и)?|блок(?:ів|и)?|одиниц(?:ь|і)|майданчик(?:ів|и)?|проєкт(?:ів|и)?|км|м²|м3|м³|Nm³\/h|т\/год)\b)/gi,"<strong>$1</strong>");
