function validateDigestImage(file,statusId,onReady){const status=$(statusId);if(!file)return;if(!IMAGE_RULES.types.includes(file.type)){status.textContent="ПОМИЛКА: дозволені JPG, PNG або WebP.";status.className="miniwarn error";return}if(file.size>IMAGE_RULES.maxBytes){status.textContent="ПОМИЛКА: файл перевищує 10 MB.";status.className="miniwarn error";return}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const accept=(data,name,width,height,type,size,label,cls)=>{status.textContent=label+" "+width+"×"+height+" px · "+(size/1024/1024).toFixed(1)+" MB";status.className="miniwarn "+cls;onReady({data,name,width,height,type,size})};if(img.width<IMAGE_RULES.minW||img.height<IMAGE_RULES.minH){status.textContent="ПІДГОТОВКА: "+img.width+"×"+img.height+" px → автоматично 1800×2546 px…";status.className="miniwarn warn";try{const tw=IMAGE_RULES.recommendedW,th=IMAGE_RULES.recommendedH,targetRatio=tw/th,srcRatio=img.width/img.height;let sx=0,sy=0,sw=img.width,sh=img.height;if(srcRatio>targetRatio){sw=Math.round(img.height*targetRatio);sx=Math.round((img.width-sw)/2)}else if(srcRatio<targetRatio){sh=Math.round(img.width/targetRatio);sy=Math.round((img.height-sh)/2)}const canvas=document.createElement("canvas");canvas.width=tw;canvas.height=th;const ctx=canvas.getContext("2d",{alpha:false});ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality="high";ctx.drawImage(img,sx,sy,sw,sh,0,0,tw,th);const outType=file.type==="image/webp"?"image/webp":"image/jpeg";canvas.toBlob(blob=>{if(!blob){status.textContent="ПОМИЛКА: не вдалося підготувати фон.";status.className="miniwarn error";return}if(blob.size>IMAGE_RULES.maxBytes){status.textContent="ПОМИЛКА: підготовлений файл перевищує 10 MB.";status.className="miniwarn error";return}const rr=new FileReader();rr.onload=()=>accept(rr.result,(file.name.replace(/\.[^.]+$/,"")||"digest-cover")+"-1800x2546."+(outType==="image/webp"?"webp":"jpg"),tw,th,outType,blob.size,"АВТОКОРЕКЦІЯ OK:","ok");rr.readAsDataURL(blob)},outType,.94)}catch(e){console.error("[IIG] Digest cover auto-resize failed",e);status.textContent="ПОМИЛКА: "+img.width+"×"+img.height+" px. Мінімум "+IMAGE_RULES.minW+"×"+IMAGE_RULES.minH+" px.";status.className="miniwarn error"}return}const recommended=img.width>=IMAGE_RULES.recommendedW&&img.height>=IMAGE_RULES.recommendedH;accept(reader.result,file.name,img.width,img.height,file.type,file.size,recommended?"ЯКІСТЬ OK:":"ПРИЙНЯТО, але нижче рекомендованого:",recommended?"ok":"warn")};img.onerror=()=>{status.textContent="ПОМИЛКА: зображення не читається.";status.className="miniwarn error"};img.src=reader.result};reader.readAsDataURL(file)}
