function autoFillDigest(showMessage=true){const extras=digestPages.filter(p=>p.kind==="promo"||p.kind==="article");digestPages=digestPages.filter((p,i)=>i<3);digestPages.forEach(p=>p.items=[]);digestOverflowExcluded=[];const pool=approved().filter(n=>digestRubric(n)!=="ADVICE"&&issueMatches(n)).map(makeDigestItem),general=pool.filter(x=>x.rubric==="GENERAL"),finance=pool.filter(x=>x.rubric==="FINANCE"),regulation=pool.filter(x=>x.rubric==="REGULATION"),newsPage=digestPages.find(x=>x.kind==="news");for(const item of general){if(newsPage&&pageFits(newsPage,item))newsPage.items.push(item);else digestOverflowExcluded.push(item)}const fcopy=[...finance],rcopy=[...regulation],balanced=packBalancedFinancePage(fcopy,rcopy),remaining=[...finance,...regulation].filter(x=>!balanced.used.has(x.slug));digestOverflowExcluded.push(...remaining);digestPages.push(...extras);persistDigestLayout();auditEvent("Автозаповнення дайджесту",pool.length+" матеріалів","3-PAGE STANDARD · INCLUDED "+(pool.length-digestOverflowExcluded.length)+" · EXCLUDED "+digestOverflowExcluded.length);renderDigest();if(showMessage)gate("Автозаповнення завершено за стандартом 3 сторінок. Матеріали, що не вмістилися, не створюють Page 4 і залишаються поза поточним випуском: "+digestOverflowExcluded.length+". Page 4+ додається тільки вручну для IIG ORIGINAL / partner / promo матеріалів.")}
