async function loadAdminReviewHandoff(){try{const d=await json("content/admin-review/latest.json");if(!d||d.status!=="ADMIN_REVIEW"||!Array.isArray(d.items))return 0;const reviewItems=d.items.map(x=>x.item).filter(Boolean).map(x=>({...x,content_type:x.type==="chief-engineer-advice"?"ADVICE":"NEWS",status:"REVIEW",admin_approved:false}));const map=new Map(items.map(x=>[x.slug||x.canonical_url,x]));for(const x of reviewItems)map.set(x.slug||x.canonical_url,x);items=[...map.values()];renderNews();renderLibrary();renderReleaseReadiness();auditEvent("Завантажено ADMIN_REVIEW handoff",String(d.run_id||""),reviewItems.length+" items");return reviewItems.length}catch(e){return 0}}
async function pollEditorialRefresh(id){
 clearInterval(editorialRefreshPoll);
 const tick=async()=>{try{const r=await fetch("/api/v1/editorial/refresh/"+encodeURIComponent(id),{cache:"no-store",credentials:"same-origin"});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||("HTTP "+r.status));
  if(d.status==="COMPLETE"){clearInterval(editorialRefreshPoll);clearInterval(dashboardRefreshTimer);setDashboardRefreshState("ГОТОВО · ADMIN REVIEW","green");await loadContent(true);const n=await loadAdminReviewHandoff();adminToast("Robot-run завершено. У ADMIN REVIEW завантажено "+n+" матеріалів.");auditEvent("Editorial Robot-run","Robots #1–#4","COMPLETE")}
  else if(d.status==="FAILED"){clearInterval(editorialRefreshPoll);clearInterval(dashboardRefreshTimer);setDashboardRefreshState("ПОМИЛКА ROBOT-RUN","red");gate("Editorial Robot-run завершився помилкою. Перевірте backend/Audit log.");auditEvent("Editorial Robot-run","Robots #1–#4","FAILED")}
  else setDashboardRefreshState(d.status==="RUNNING"?"ROBOT-RUN · RUNNING":"ROBOT-RUN · QUEUED","amber");
 }catch(e){clearInterval(editorialRefreshPoll);clearInterval(dashboardRefreshTimer);setDashboardRefreshState("BACKEND НЕДОСТУПНИЙ","red");gate("Не вдалося отримати статус Robot-run. GitHub автоматично не відкривається. Потрібен підключений /api/v1/editorial/refresh.");}};
 await tick();editorialRefreshPoll=setInterval(tick,5000);
}
